import UserBoxs from "../UsersBoxs/UserBoxs";
import users from "../../constants/data";

import "./DataGeneration.css";

function DataGeneration({index, id, name, username, email, phone, website}) {
  return (
    <div className="mainData">
              <UserBoxs
          key={index}
          id={id}
          name={name}
          username={username}
          email={email}
          phone={phone}
          website={website}
        />

    </div>
  );
}

export default DataGeneration;
